#!/bin/sh
dotfiles_export(){ out=${1:-$CURRENT_HOME/ish-aok-dotfiles.tar.gz}; files=''; for f in .profile .bashrc .bash_profile .zshrc .ashrc .inputrc .nanorc .vimrc .gitconfig .tmux.conf .screenrc .ssh/config .config/starship.toml .config/micro/settings.json .config/helix/config.toml; do [ -e "$CURRENT_HOME/$f" ] && files="$files $f"; done; (cd "$CURRENT_HOME" && tar -czf "$out" $files); ui_msg Dotfiles "Created $out"; }
dotfiles_hooks_menu(){ while :; do c=$(ui_menu 'Dotfiles and custom hooks' 'Export, import, compare, synchronize, and manage hook scripts.' export 'Export dotfiles archive' import 'Import dotfiles archive' git 'Initialize dotfiles Git repository' compare 'Compare two configuration files' sync 'Copy dotfiles to another rootfs' startup 'Manage startup scripts' login 'Manage login scripts' backup 'Manage backup hooks' build 'Manage build hooks' back Back) || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in export) o=$(ui_input Export 'Archive path' "$CURRENT_HOME/ish-aok-dotfiles.tar.gz") || continue; dotfiles_export "$o";; import) a=$(ui_input Import 'Archive path' '') || continue; backup_common 2>/dev/null || true; tar -xzf "$a" -C "$CURRENT_HOME";; git) d="$CURRENT_HOME/.dotfiles"; mkdir -p "$d"; git -C "$d" init; ui_msg Git "Initialized $d. Add files or use a work-tree strategy.";; compare) a=$(ui_input Compare 'First file' "$CURRENT_HOME/.bashrc") || continue; b=$(ui_input Compare 'Second file' "$CURRENT_HOME/.profile") || continue; run_capture Diff diff -u "$a" "$b";; sync) r=$(ui_input Sync 'Target rootfs' /root/rootfs) || continue; for f in .profile .bashrc .zshrc .nanorc .vimrc .gitconfig .tmux.conf; do [ -f "$CURRENT_HOME/$f" ] && { mkdir -p "$r$CURRENT_HOME"; cp -p "$CURRENT_HOME/$f" "$r$CURRENT_HOME/$f"; }; done;; startup) mkdir -p "$CURRENT_HOME/.config/ish-aok/hooks"; edit_file "$CURRENT_HOME/.config/ish-aok/hooks/startup.sh";; login) edit_file "$CURRENT_HOME/.profile";; backup) mkdir -p "$CURRENT_HOME/.config/ish-aok/hooks"; edit_file "$CURRENT_HOME/.config/ish-aok/hooks/backup.sh";; build) mkdir -p "$CURRENT_HOME/.config/ish-aok/hooks"; edit_file "$CURRENT_HOME/.config/ish-aok/hooks/build.sh";; back) return;; esac; done; }
